from Registry import Registry
import sys
import datetime

def convert_filetime(ft):
    EPOCH_AS_FILETIME = 116444736000000000  # January 1, 1970 as MS FILETIME
    microseconds = (ft - EPOCH_AS_FILETIME) // 10
    return datetime.datetime(1970, 1, 1) + datetime.timedelta(microseconds=microseconds)

def analyze_sam(sam_path):
    print("\n=== Analyzing SAM Hive ===")
    reg = Registry.Registry(sam_path)

    users_key = reg.open('SAM\\Domains\\Account\\Users')
    names_key = reg.open('SAM\\Domains\\Account\\Users\\Names')

    print("\nUser Accounts Found:")
    for subkey in names_key.subkeys():
        print(f"\nUsername: {subkey.name()}")

        # Get the user's RID from the Names key
        for sk in users_key.subkeys():
            if sk.name() != 'Names':
                try:
                    f_val = sk.value('F').value()
                    if f_val[0x0c:0x10].decode('utf-16-le').strip('\x00') == subkey.name():
                        print(f"RID: {sk.name()}")
                        last_login = int.from_bytes(f_val[0x20:0x28], byteorder='little')
                        if last_login:
                            print(f"Last Login: {convert_filetime(last_login)}")
                        else:
                            print("Last Login: Never")

                        # Check if user is an administrator
                        if f_val[0x38] & 0x20:  # Check admin flag
                            print("Account Type: Administrator")
                        else:
                            print("Account Type: Regular User")
                except:
                    continue

