import datetime

def windows_timestamp_to_datetime(timestamp):
    try:
        if timestamp == 0:
            return "Never"
        # Windows timestamps are in 100-nanosecond intervals since January 1, 1601
        seconds_since_1601 = timestamp / 10000000
        epoch_adj = datetime.datetime(1970, 1, 1) - datetime.datetime(1601, 1, 1)
        seconds_since_epoch = seconds_since_1601 - epoch_adj.total_seconds()
        return datetime.datetime.fromtimestamp(seconds_since_epoch)
    except:
        return "Invalid timestamp"

