from datetime import datetime, timedelta
import struct

def convert_win32_timestamp(timestamp):
    # Convert Windows timestamp (100-nanosecond intervals since January 1, 1601)
    # to Unix timestamp and then to datetime object
    WINDOWS_TICK = 10000000  # 100 nanoseconds
    SEC_TO_UNIX_EPOCH = 11644473600  # seconds from 1601 to 1970

    if isinstance(timestamp, bytes):
        timestamp = struct.unpack("<Q", timestamp)[0]

    seconds_since_1601 = timestamp / WINDOWS_TICK
    unix_timestamp = seconds_since_1601 - SEC_TO_UNIX_EPOCH

    dt = datetime.utcfromtimestamp(unix_timestamp)
    # Convert to UTC+8
    dt = dt + timedelta(hours=8)
    return dt

def parse_sam_user(v_value):
    # Parse user V value structure
    last_login_offset = 0x8C  # Typically where LastLogin is stored
    timestamp = None

    if len(v_value) >= last_login_offset + 8:
        timestamp_bytes = v_value[last_login_offset:last_login_offset + 8]
        if timestamp_bytes != b'\x00' * 8:
            try:
                timestamp = convert_win32_timestamp(timestamp_bytes)
            except:
                pass
    return timestamp

def find_spectre_lastlogin():
