from Registry.Registry import Registry
import struct
from datetime import datetime, timedelta

def filetime_to_datetime(ft):
    if ft == 0:
        return "Never"
    if ft == 0x7fffffffffffffff:
        return "MAX_TIME (Potential hidden value)"
    try:
        microseconds = (ft - 116444736000000000) // 10
        return datetime(1970, 1, 1) + timedelta(microseconds=microseconds)
    except OverflowError:
        return f"OVERFLOW - Raw value: 0x{ft:016x}"

def decode_samr_user_info(user_data):
    timestamps = {
        "Last Logon": struct.unpack("<Q", user_data[8:16])[0],
        "Last Logoff": struct.unpack("<Q", user_data[16:24])[0],
        "Last Pwd Reset": struct.unpack("<Q", user_data[24:32])[0],
        "Account Creation": struct.unpack("<Q", user_data[32:40])[0],
        "Last Pwd Fail": struct.unpack("<Q", user_data[40:48])[0]
    }

    print("\nRaw Values (Hex):")
    for name, value in timestamps.items():
        print(f"{name:16}: 0x{value:016x}")

    print("\nConverted Timestamps (UTC):")
    for name, value in timestamps.items():
        dt = filetime_to_datetime(value)
        print(f"{name:16}: {dt}")
        if isinstance(dt, datetime):
            # Show potential DST-adjusted time
            print(f"{name} (DST): {dt + timedelta(hours=1)}")

def analyze_sam_users():
    sam = Registry("SAM")
    users_key = sam.open("SAM\\Domains\\Account\\Users")

    print("=== Detailed SAM User Timestamp Analysis ===")

    for subkey in users_key.subkeys():
        if subkey.name() == "Names":
            continue

        print(f"\nAnalyzing User RID: {subkey.name()}")
        for value in subkey.values():
            if value.name() == "F":
                print(f"Registry Key Path: SAM\\Domains\\Account\\Users\\{subkey.name()}")
                decode_samr_user_info(value.value())

def analyze_system_time():
    try:
        system = Registry("SYSTEM")
        tz_key = system.open("ControlSet001\\Control\\TimeZoneInformation")
        print("\n=== System Time Configuration ===")
        for value in tz_key.values():
            print(f"{value.name():20}: {value.value()}")
    except Exception as e:
        print(f"Error analyzing system time: {e}")

if __name__ == "__main__":
    analyze_sam_users()
    analyze_system_time()

